def test_empty_inputs():
    assert merge_inventory({}, {}) == {}


def test_incoming_adds_to_base():
    assert merge_inventory({"A": 2}, {"A": 5}) == {"A": 7}


def test_zero_counts():
    assert merge_inventory({"A": 0}, {"A": 0}) == {"A": 0}


def test_inputs_not_mutated():
    base = {"A": 1, "B": 2}
    incoming = {"A": 10, "C": 3}
